const totalSafe=(items)=>items.filter(x=>x.status==='Active').reduce((sum,x)=>sum+monthly(x),0);
const iso=(d)=>{const x=new Date(d);return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`};
const parseDate=(s)=>new Date(`${s}T12:00:00`);
const money=(n,symbol='₱')=>formatCurrency(n,symbol);
const addCycle=(date,cycle,n=1)=>{const d=parseDate(date);if(cycle==='Weekly'){d.setDate(d.getDate()+7*n);return iso(d)}const months=cycle==='Yearly'?12*n:cycle==='Quarterly'?3*n:n;const day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+months);const lastDay=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();d.setDate(Math.min(day,lastDay));return iso(d)};
const nextDate=(s)=>{let d=s.next_date;let i=0;while(parseDate(d)<parseDate(iso(new Date()))&&i++<1000)d=addCycle(d,s.cycle);return d};
const monthly=(s)=>Number(s.price)*(s.cycle==='Weekly'?52/12:s.cycle==='Yearly'?1/12:s.cycle==='Quarterly'?1/3:1);
const shortDate=(s)=>parseDate(s).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});
