async function initialize(db){await db.execAsync(`PRAGMA journal_mode = WAL;
CREATE TABLE IF NOT EXISTS categories (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL UNIQUE,color TEXT NOT NULL,icon TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS subscriptions (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,price REAL NOT NULL,cycle TEXT NOT NULL,next_date TEXT NOT NULL,category_id INTEGER,notes TEXT DEFAULT '',status TEXT DEFAULT 'Active',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS payments (id INTEGER PRIMARY KEY AUTOINCREMENT,subscription_id INTEGER NOT NULL,service_name TEXT NOT NULL,amount REAL NOT NULL,paid_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS preferences (key TEXT PRIMARY KEY,value TEXT NOT NULL);`);
const columns=await db.getAllAsync('PRAGMA table_info(subscriptions)');
if(!columns.some(c=>c.name==='image_uri'))await db.execAsync('ALTER TABLE subscriptions ADD COLUMN image_uri TEXT');
for(const [column,type] of [['home_url','TEXT'],['manage_url','TEXT'],['trial_end','TEXT'],['reminder_days','TEXT']]){
 if(!columns.some(c=>c.name===column))await db.execAsync(`ALTER TABLE subscriptions ADD COLUMN ${column} ${type}`);
}
await db.execAsync(`CREATE TABLE IF NOT EXISTS price_history (id INTEGER PRIMARY KEY AUTOINCREMENT,subscription_id INTEGER NOT NULL,service_name TEXT NOT NULL,old_price REAL NOT NULL,new_price REAL NOT NULL,changed_at TEXT NOT NULL);`);

for(const [name,color,icon] of DEFAULT_CATS)await db.runAsync('INSERT OR IGNORE INTO categories (name,color,icon) VALUES (?,?,?)',name,color,icon);
}
const REMINDER_CHANNEL='subtrack-renewals-v3';
const REMINDER_TAG='subtrack-renewal';
let reminderQueue=Promise.resolve();
function queueReminderSync(task){const run=reminderQueue.catch(()=>{}).then(task);reminderQueue=run.catch(e=>console.warn('Reminder sync failed:',e));return run;}
async function configureReminderChannel(){
  if(Platform.OS!=='android')return null;
  try{
    await Notifications.setNotificationChannelAsync(REMINDER_CHANNEL,{
      name:'Subscription renewals',
      importance:Notifications.AndroidImportance.HIGH,
      sound:'default',
      vibrationPattern:[0,250,250,250],
      enableVibrate:true,
    });
    return REMINDER_CHANNEL;
  }catch(error){
    console.warn('Could not configure custom Android notification channel; trying default:',error);
    return 'default';
  }
}
async function syncReminders(subscriptions,preferences){
  const channelId=await configureReminderChannel();
  const existing=await Notifications.getAllScheduledNotificationsAsync();
  for(const item of existing){if(item.content?.data?.source===REMINDER_TAG)await Notifications.cancelScheduledNotificationAsync(item.identifier);}
  if(preferences.reminders!=='true')return 0;
  const permission=await Notifications.getPermissionsAsync();
  if(!permission.granted)return 0;
  let count=0;
  for(const s of subscriptions.filter(x=>x.status==='Active')){
    const renewal=nextDate(s);
    const offsets=[...new Set(String(s.reminder_days||preferences.reminderDays||'3').split(',').map(Number).filter(n=>Number.isInteger(n)&&n>=0&&n<=365))];
    for(const offset of offsets){
      const date=parseDate(renewal);date.setDate(date.getDate()-offset);date.setHours(9,0,0,0);
      if(!Number.isFinite(date.getTime())||date<=new Date())continue;
      await Notifications.scheduleNotificationAsync({
        content:{title:`${s.name} renewal reminder`,body:`Payment due ${shortDate(renewal)}.`,sound:'default',data:{source:REMINDER_TAG,subscriptionId:s.id}},
        trigger:{type:Notifications.SchedulableTriggerInputTypes.DATE,date,...(Platform.OS==='android'?{channelId}:{})},
      });count++;
    }
    if(s.trial_end){const d=parseDate(s.trial_end);d.setDate(d.getDate()-1);d.setHours(9,0,0,0);if(d>new Date()){await Notifications.scheduleNotificationAsync({content:{title:`${s.name} free trial ending`,body:`Trial ends ${shortDate(s.trial_end)}. Review your plan.`,data:{source:REMINDER_TAG,subscriptionId:s.id}},trigger:{type:Notifications.SchedulableTriggerInputTypes.DATE,date:d,...(Platform.OS==='android'?{channelId}:{})}});count++;}}
  }
  return count;
}
function validateBackup(data){
  const fail=(why)=>{throw Error('Backup validation failed: '+why)};
  if(!data||typeof data!=='object'||Array.isArray(data)||data.version!==1)fail('unsupported backup format or version');
  for(const key of ['subscriptions','categories','payments'])if(!Array.isArray(data[key])||data[key].length>20000)fail('invalid '+key);
  const ids=(rows,key)=>{const seen=new Set();for(const row of rows){if(!row||typeof row!=='object'||!Number.isSafeInteger(row.id)||row.id<=0||seen.has(row.id))fail('invalid or duplicate '+key+' ID');seen.add(row.id);}return seen;};
  const catIds=ids(data.categories,'category'),subIds=ids(data.subscriptions,'subscription');ids(data.payments,'payment');
  const validDate=s=>typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&Number.isFinite(parseDate(s).getTime())&&iso(parseDate(s))===s;
  for(const c of data.categories)if(typeof c.name!=='string'||!c.name.trim()||c.name.length>200||typeof c.color!=='string'||typeof c.icon!=='string')fail('invalid category');
  if(new Set(data.categories.map(c=>c.name)).size!==data.categories.length)fail('duplicate category names');
  for(const s of data.subscriptions){if(s.image_uri!=null&&(typeof s.image_uri!=='string'||(s.image_uri.length>3000000)||(!s.image_uri.startsWith('data:image/jpeg;base64,')&&!s.image_uri.startsWith('data:image/png;base64,'))))fail('invalid subscription image');if(typeof s.name!=='string'||!s.name.trim()||s.name.length>250||typeof s.price!=='number'||!Number.isFinite(s.price)||s.price<0||!['Weekly','Monthly','Quarterly','Yearly'].includes(s.cycle)||!validDate(s.next_date)||!['Active','Paused','Cancelled','Archived'].includes(s.status||'Active')||(s.category_id!=null&&!catIds.has(s.category_id))||(s.notes!=null&&typeof s.notes!=='string')||['home_url','manage_url','trial_end','reminder_days'].some(k=>s[k]!=null&&typeof s[k]!=='string'))fail('invalid subscription');}
  for(const p of data.payments)if(!Number.isSafeInteger(p.subscription_id)||typeof p.service_name!=='string'||!p.service_name.trim()||typeof p.amount!=='number'||!Number.isFinite(p.amount)||p.amount<0||!validDate(p.paid_at))fail('invalid payment');
  if(data.price_history!=null){if(!Array.isArray(data.price_history)||data.price_history.length>50000)fail('invalid price history');for(const h of data.price_history){if(!Number.isSafeInteger(h.id)||h.id<=0||!Number.isSafeInteger(h.subscription_id)||typeof h.service_name!=='string'||!Number.isFinite(h.old_price)||!Number.isFinite(h.new_price)||!validDate(h.changed_at))fail('invalid price history entry');}}
  if(data.preferences!=null&&(!data.preferences||typeof data.preferences!=='object'||Array.isArray(data.preferences)))fail('invalid preferences');
  return data;
}
