const pickSubscriptionImage=async()=>{
  try{
    const permission=await ImagePicker.requestMediaLibraryPermissionsAsync();
    if(!permission.granted){Alert.alert('Photo permission needed','Allow photo access to choose a subscription logo.');return;}
    const result=await ImagePicker.launchImageLibraryAsync({mediaTypes:['images'],allowsEditing:true,aspect:[1,1],quality:0.5,base64:true});
    if(result.canceled||!result.assets?.[0])return;
    const asset=result.assets[0];
    if(!asset.base64){Alert.alert('Image unavailable','Please select another image.');return;}
    if(asset.base64.length>2800000){Alert.alert('Image too large','Please choose a smaller photo.');return;}
    const mime=asset.mimeType==='image/png'?'image/png':'image/jpeg';
    setForm(f=>({...f,image_uri:`data:${mime};base64,${asset.base64}`}));
  }catch(e){Alert.alert('Image selection failed',e.message);}
};
