if(screen==='analytics'){const byCat=cats.map(c=>({...c,value:active.filter(s=>s.category_id===c.id).reduce((a,s)=>a+monthly(s),0)})).filter(c=>c.value>0);const other=active.filter(s=>!cats.some(c=>c.id===s.category_id)).reduce((a,s)=>a+monthly(s),0);if(other)byCat.push({name:'Uncategorized',color:'#999999',value:other});let offset=0;return <>{header('Analytics')}{choice('Period',['Monthly','Yearly'],analyticsMode,setAnalyticsMode)}{card(<View style={{alignItems:'center'}}>{text(analyticsMode==='Monthly'?'Monthly Spending':'Annual Projection',13,false,t.muted)}{text(money(total*(analyticsMode==='Yearly'?12:1),sym),28,true,t.text,{marginTop:7})}<View style={{marginTop:20,marginBottom:15,alignItems:'center',justifyContent:'center'}}><Svg width={190} height={190}><Circle cx={95} cy={95} r={69} stroke={t.line} strokeWidth={25} fill="none"/>{byCat.map((c,i)=>{let len=c.value/(total||1)*433.54;let start=offset;offset+=len;return <Circle key={i} cx={95} cy={95} r={69} stroke={c.color} strokeWidth={25} fill="none" strokeDasharray={`${len} ${433.54-len}`} strokeDashoffset={-start} rotation={-90} origin="95,95"/>})}</Svg><View style={{position:'absolute',alignItems:'center'}}>{text(money(total,sym),17,true)}{text('per month',11,false,t.muted)}</View></View></View>)}{byCat.map(c=><View key={c.name} style={{flexDirection:'row',alignItems:'center',gap:12,paddingVertical:13,paddingHorizontal:14,backgroundColor:t.card,borderRadius:13,borderWidth:1,borderColor:t.line,marginBottom:7}}><CategoryMarker category={c} size={13}/><View style={{flex:1}}>{text(c.name,13,true,t.text)}{text(`${Math.round(c.value/(total||1)*100)}% of recurring spending`,11,false,t.muted,{marginTop:3})}</View>{text(money(c.value*(analyticsMode==='Yearly'?12:1),sym),13,true,t.text)}</View>)}{!byCat.length&&text('Add subscriptions to see spending analytics.',13,false,t.muted)}{budgetPanel()}{text('Actual Payments · Last 6 Months',17,true,t.text,{marginTop:15,marginBottom:10})}{card(<>{text('Based on payments marked as paid, not estimated subscription charges.',11,false,t.muted,{marginBottom:15})}{(()=>{const trend=historyTrend(),max=Math.max(1,...trend.map(x=>x.amount));return <View style={{flexDirection:'row',alignItems:'flex-end',justifyContent:'space-between',height:165}}>{trend.map(x=><View key={x.key} style={{width:'15%',alignItems:'center',justifyContent:'flex-end'}}>{text(x.amount?money(x.amount,sym):'0',9,false,t.muted,{marginBottom:5})}<View style={{width:'80%',height:Math.max(5,110*x.amount/max),backgroundColor:t.purple,borderRadius:5}}/>{text(x.label,11,true,t.muted,{marginTop:7})}</View>)}</View>})()}</>)}{text('Most Expensive Subscriptions',17,true,t.text,{marginTop:15,marginBottom:10})}{[...active].sort((a,b)=>monthly(b)-monthly(a)).slice(0,5).map((s,i)=><View key={s.id}>{row('trending-up-outline',`${i+1}. ${s.name}`,`${money(monthly(s),sym)} per month`,()=>{setSelected(s);go('details')})}</View>)}{!active.length&&text('No active subscriptions yet.',12,false,t.muted)}<View style={{height:30}}/><FinancialInsights subscriptions={subs} payments={payments} budget={budget} t={t} symbol={sym}/></>}
