if(screen==='settings')return <>{text('Settings',23,true,t.text,{marginBottom:17})}{card(<>{row('wallet-outline','Monthly Budget',budget?money(budget,sym):'Not set',()=>{setBudgetInput(budget?String(budget):'');go('budget')})}{row('moon-outline','Appearance',prefs.theme==='light'?'Light mode':'Dark mode',()=>go('appearance'))}{row('pricetags-outline','Categories','Manage subscription categories',()=>go('categories'))}{row('notifications-outline','Notifications','Renewal reminders',()=>go('notifications'))}{row('calendar-outline','Renewal Calendar','View billing dates',()=>go('calendar'))}{row('receipt-outline','Payment History','View past payments',()=>go('history'))}{row('cloud-upload-outline','Backup & Restore','Export or import your data',()=>go('backup'))}{row('cash-outline','Currency',prefs.currency==='₱'?'Philippine Peso':'US Dollar',()=>go('currency'))}{row('information-circle-outline','About','SubNest v1.1.0',()=>go('about'))}</>)}</>;
